// RESPONSIBILITY: Defines runtime validation schemas for plans_catalog; it does not determine server-owned business rules without a verified contract.
// DATA FLOW: API/form boundary → Zod schema → validated typed data or field-level errors → owning hook/view (admin_plans/plans_catalog/schemas/AdminBillingPlansCatalogSchemas.ts)

import { z } from 'zod';
import { TIERS } from '@/app/frontend_admin/admin_billing/billing_plans_catalog/constants/admin_billing_plans_catalog.constants';
// Generated by ts-to-zod


export const statusSchema = z.union([z.literal("idle"), z.literal("loading"), z.literal("success"), z.literal("error")]);

export const planSchema = z.object({
    id: z.string(),
    name: z.string(),
    tier: z.enum(TIERS),
    price1Month: z.number().int().nonnegative(),
    price3Month: z.number().int().nonnegative(),
    price6Month: z.number().int().nonnegative(),
    price12Month: z.number().int().nonnegative(),
    priceCustom: z.number().int().nonnegative().optional(),
    features: z.array(z.string()),
    isActive: z.boolean(),
    freezeAllowed: z.boolean().optional(),
    joiningFee: z.number().int().nonnegative().optional(),
    ptSessionsIncluded: z.number().optional(),
    taxRate: z.number().optional()
});



export const plansInitialDataSchema = z.object({
    plans: z.array(planSchema)
});

// Validate entered decimal precision lexically, not with Number(value) * 100 === integer.
// Number.isSafeInteger guards against payloads exceeding the minor-unit API's safe range.
const planMoneyFormSchema = z.string().trim()
  .min(1, '__i18n:plans.validation.validPrice')
  .refine(value => /^\d+(?:\.\d{1,2})?$/.test(value) && Number.isFinite(Number(value)) && Number(value) >= 0,
    '__i18n:plans.validation.validPrice')
  .refine(value => !/^\d+(?:\.\d+)?$/.test(value) ||
    (value.split('.')[1]?.length ?? 0) <= 2 && Number.isSafeInteger(Math.round(Number(value) * 100)),
    '__i18n:plans.validation.maxTwoDecimals');

export const planFormSchema = z.object({
  name: z.string().min(2, '__i18n:plans.validation.nameRequired'),
  tier: z.enum(TIERS),
  price1Month: planMoneyFormSchema,
  price3Month: planMoneyFormSchema,
  price6Month: planMoneyFormSchema,
  price12Month: planMoneyFormSchema,
  priceCustom: planMoneyFormSchema,
  features: z.string().min(2, '__i18n:plans.validation.featuresRequired')
});
